  ck(throws([&]{a.add({U'C',{63,0,2,2},0,2,9});}),"glyph out of atlas");
  ck(throws([&]{a.add({U'C',{32,0,8,10},0,2,0});}),"glyph zero advance");
  ck(throws([&]{a.add({U'C',{32,0,8,10},0,2,INFINITY});}),"glyph infinite advance");
